13	describe('mcpToolWrapper', () => {
14	  let mockBrowserManager: BrowserManager;
15	  let mockMessageBus: MessageBus;
16	  let mockMcpTools: McpTool[];
17	
18	  beforeEach(() => {
19	    vi.resetAllMocks();
20	
21	    // Setup mock MCP tools discovered from server
22	    mockMcpTools = [
23	      {
24	        name: 'take_snapshot',
25	        description: 'Take a snapshot of the page accessibility tree',
26	        inputSchema: {
27	          type: 'object',
28	          properties: {
29	            verbose: { type: 'boolean', description: 'Include details' },
30	          },
31	        },
32	      },
33	      {
34	        name: 'click',
35	        description: 'Click on an element by uid',
36	        inputSchema: {
37	          type: 'object',
38	          properties: {
39	            uid: { type: 'string', description: 'Element uid' },
40	          },
41	          required: ['uid'],
42	        },
43	      },
44	    ];
45	
46	    // Setup mock browser manager
47	    mockBrowserManager = {
48	      getDiscoveredTools: vi.fn().mockResolvedValue(mockMcpTools),
49	      callTool: vi.fn().mockResolvedValue({
50	        content: [{ type: 'text', text: 'Tool result' }],
51	      } as McpToolCallResult),
52	    } as unknown as BrowserManager;
53	
54	    // Setup mock message bus
55	    mockMessageBus = {
56	      publish: vi.fn().mockResolvedValue(undefined),
57	      subscribe: vi.fn(),
58	      unsubscribe: vi.fn(),
59	    } as unknown as MessageBus;
60	  });
61	
62	  afterEach(() => {
63	    vi.restoreAllMocks();
64	  });
65	
66	  describe('createMcpDeclarativeTools', () => {
67	    it('should create declarative tools from discovered MCP tools', async () => {
68	      const tools = await createMcpDeclarativeTools(
69	        mockBrowserManager,
70	        mockMessageBus,
71	      );
72	
73	      expect(tools).toHaveLength(3);
74	      expect(tools[0].name).toBe('take_snapshot');
75	      expect(tools[1].name).toBe('click');
76	      expect(tools[2].name).toBe('type_text');
77	    });
78	
79	    it('should return tools with correct description', async () => {
80	      const tools = await createMcpDeclarativeTools(
81	        mockBrowserManager,
82	        mockMessageBus,
83	      );
84	
85	      // Descriptions include augmented hints, so we check they contain the original
86	      expect(tools[0].description).toContain(
87	        'Take a snapshot of the page accessibility tree',
88	      );
89	      expect(tools[1].description).toContain('Click on an element by uid');
90	    });
91	
92	    it('should return tools with proper FunctionDeclaration schema', async () => {
93	      const tools = await createMcpDeclarativeTools(
94	        mockBrowserManager,
95	        mockMessageBus,
96	      );
97	
98	      const schema = tools[0].schema;
99	      expect(schema.name).toBe('take_snapshot');
100	      expect(schema.parametersJsonSchema).toBeDefined();
101	    });
102	  });
103	
104	  describe('McpDeclarativeTool.build', () => {
105	    it('should create invocation that can be executed', async () => {
106	      const tools = await createMcpDeclarativeTools(
107	        mockBrowserManager,
108	        mockMessageBus,
109	      );
110	
111	      const invocation = tools[0].build({ verbose: true });
112	
113	      expect(invocation).toBeDefined();
114	      expect(invocation.params).toEqual({ verbose: true });
115	    });
116	
117	    it('should return invocation with correct description', async () => {
118	      const tools = await createMcpDeclarativeTools(
119	        mockBrowserManager,
120	        mockMessageBus,
121	      );
122	
123	      const invocation = tools[0].build({});
124	
125	      expect(invocation.getDescription()).toContain('take_snapshot');
126	    });
127	  });
128	
129	  describe('McpToolInvocation.execute', () => {
130	    it('should call browserManager.callTool with correct params', async () => {
131	      const tools = await createMcpDeclarativeTools(
132	        mockBrowserManager,
133	        mockMessageBus,
134	      );
135	
136	      const invocation = tools[1].build({ uid: 'elem-123' });
137	      await invocation.execute(new AbortController().signal);
138	
139	      expect(mockBrowserManager.callTool).toHaveBeenCalledWith(
140	        'click',
141	        {
142	          uid: 'elem-123',
143	        },
144	        expect.any(AbortSignal),
145	      );
146	    });
147	
148	    it('should return success result from MCP tool', async () => {
149	      const tools = await createMcpDeclarativeTools(
150	        mockBrowserManager,
151	        mockMessageBus,
152	      );
153	
154	      const invocation = tools[0].build({ verbose: true });
155	      const result = await invocation.execute(new AbortController().signal);
156	
157	      expect(result.llmContent).toBe('Tool result');
158	      expect(result.error).toBeUndefined();
159	    });
160	
161	    it('should handle MCP tool errors', async () => {
162	      vi.mocked(mockBrowserManager.callTool).mockResolvedValue({
163	        content: [{ type: 'text', text: 'Element not found' }],
164	        isError: true,
165	      } as McpToolCallResult);
166	
167	      const tools = await createMcpDeclarativeTools(
168	        mockBrowserManager,
169	        mockMessageBus,
170	      );
171	
172	      const invocation = tools[1].build({ uid: 'invalid' });
173	      const result = await invocation.execute(new AbortController().signal);
174	
175	      expect(result.error).toBeDefined();
176	      expect(result.error?.message).toBe('Element not found');
177	    });
178	
179	    it('should handle exceptions during tool call', async () => {
180	      vi.mocked(mockBrowserManager.callTool).mockRejectedValue(
181	        new Error('Connection lost'),
182	      );
183	
184	      const tools = await createMcpDeclarativeTools(
185	        mockBrowserManager,
186	        mockMessageBus,
187	      );
188	
189	      const invocation = tools[0].build({});
190	      const result = await invocation.execute(new AbortController().signal);
191	
192	      expect(result.error).toBeDefined();
193	      expect(result.error?.message).toBe('Connection lost');
194	    });
195	  });
196	});
