162	): Promise<void> {
163	  try {
164	    await browserManager.close();
165	    debugLogger.log('Browser agent cleanup complete');
166	  } catch (error) {
167	    debugLogger.error(
168	      `Error during browser cleanup: ${error instanceof Error ? error.message : String(error)}`,
169	    );
170	  }
171	}
