/**
 * @fileoverview Input-blocking overlay utilities for automated browser control.
 *
 * While the browser agent performs interactive operations (click, fill, type,
 * etc.) the user should not be able to interfere by moving the mouse or typing
 * into the page. These utilities inject a full-screen overlay that captures and
 * discards user input, and remove it once the automated session finishes.
 *
 * The overlay is temporarily "suspended" (its pointer-events disabled) around
 * each automated interaction so the agent's own synthetic events reach the page,
 * then "resumed" afterwards to restore the block. See mcpToolWrapper.ts.
 *
 * The script strings are passed to chrome-devtools-mcp's evaluate_script tool
 * which expects a plain function expression (NOT an IIFE). Nested template
 * literals are avoided by using string concatenation.
 */

import type { BrowserManager } from './browserManager.js';
import { debugLogger } from '../../utils/debugLogger.js';

const INPUT_BLOCKER_ELEMENT_ID = '__gemini_input_blocker';

/**
 * Builds the JavaScript function string that injects the input-blocking overlay.
 *
 * Returns a plain arrow-function expression (no trailing invocation) because
 * chrome-devtools-mcp's evaluate_script tool invokes it internally.
 */
function buildInjectionScript(): string {
  return `() => {
    const id = '${INPUT_BLOCKER_ELEMENT_ID}';
    const existing = document.getElementById(id);
    if (existing) existing.remove();

    const blocker = document.createElement('div');
    blocker.id = id;
    blocker.setAttribute('aria-hidden', 'true');
    blocker.setAttribute('role', 'presentation');
    blocker.title = 'Gemini CLI is controlling this browser';

    Object.assign(blocker.style, {
      position: 'fixed',
      top: '0',
      left: '0',
      right: '0',
      bottom: '0',
      zIndex: '2147483646',
      pointerEvents: 'auto',
      cursor: 'not-allowed',
      background: 'transparent',
    });

    const label = document.createElement('div');
    label.textContent = 'Gemini CLI is controlling this browser';
    Object.assign(label.style, {
      position: 'fixed',
      top: '8px',
      left: '50%',
      transform: 'translateX(-50%)',
      padding: '4px 12px',
      borderRadius: '4px',
      font: '12px sans-serif',
      color: '#fff',
      background: 'rgba(66,133,244,0.9)',
      pointerEvents: 'none',
    });
    blocker.appendChild(label);

    const swallow = (e) => {
      e.stopPropagation();
      e.preventDefault();
    };
    ['click', 'mousedown', 'mouseup', 'keydown', 'keyup', 'keypress', 'wheel', 'contextmenu']
      .forEach((type) => blocker.addEventListener(type, swallow, true));

    document.documentElement.appendChild(blocker);
    return 'input-blocker-injected';
  }`;
}

/**
 * Builds the JavaScript function string that removes the input-blocking overlay.
 */
function buildRemovalScript(): string {
  return `() => {
    const el = document.getElementById('${INPUT_BLOCKER_ELEMENT_ID}');
    if (el) el.remove();
    return 'input-blocker-removed';
  }`;
}

/**
 * Builds the script that suspends the blocker so the agent's own synthetic
 * input events can reach the page during an interactive operation.
 */
export function buildSuspendScript(): string {
  return `() => {
    const el = document.getElementById('${INPUT_BLOCKER_ELEMENT_ID}');
    if (el) el.style.pointerEvents = 'none';
    return 'input-blocker-suspended';
  }`;
}

/**
 * Builds the script that resumes the blocker after an interactive operation,
 * restoring the block on user input.
 */
export function buildResumeScript(): string {
  return `() => {
    const el = document.getElementById('${INPUT_BLOCKER_ELEMENT_ID}');
    if (el) el.style.pointerEvents = 'auto';
    return 'input-blocker-resumed';
  }`;
}

/**
 * Injects the input-blocking overlay into the current page.
 *
 * Any error from callTool is caught and the promise resolves with `undefined`
 * so that a failure to block input never aborts the automated operation.
 */
export async function injectInputBlocker(
  browserManager: BrowserManager,
  signal?: AbortSignal,
): Promise<void> {
  try {
    debugLogger.log('Injecting input blocker...');

    const result = await browserManager.callTool(
      'evaluate_script',
      { function: buildInjectionScript() },
      signal,
    );

    if (result.isError) {
      debugLogger.warn('Failed to inject input blocker:', result);
    } else {
      debugLogger.log('Input blocker injected successfully');
    }
  } catch (error) {
    debugLogger.warn('Error injecting input blocker:', error);
    return undefined;
  }
}

/**
 * Removes the input-blocking overlay from the current page.
 *
 * Any error from callTool is caught and the promise resolves with `undefined`
 * so cleanup always completes, even if the underlying operation failed.
 */
export async function removeInputBlocker(
  browserManager: BrowserManager,
  signal?: AbortSignal,
): Promise<void> {
  try {
    debugLogger.log('Removing input blocker...');

    const result = await browserManager.callTool(
      'evaluate_script',
      { function: buildRemovalScript() },
      signal,
    );

    if (result.isError) {
      debugLogger.warn('Failed to remove input blocker:', result);
    } else {
      debugLogger.log('Input blocker removed successfully');
    }
  } catch (error) {
    debugLogger.warn('Error removing input blocker:', error);
    return undefined;
  }
}
